, "approx_sec": 6.0}, {"slide_index": 9, "caption": "''और तुम भी एक साधारण शिकारी के तीर से मारे जाओगे!''", "image_prompt": "A vision of an ordinary hunter accidentally shooting a glowing arrow towards the foot of Lord Krishna in a forest, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "श्री कृष्ण ने मुस्कुराकर श्राप स्वीकार कर लिया।", "image_prompt": "Lord Krishna standing peacefully, hands folded in respect, accepting the terrible curse with a gentle, knowing smile, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "वे जानते थे कि यादव वंश का भी अंत निश्चित है।", "image_prompt": "A massive ocean wave completely swallowing the glowing golden city of Dwarka, cosmic destruction, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "भगवान भी कर्म के विधान का सम्मान करते हैं।", "image_prompt": "A glowing balance scale in the cosmos, symbolizing ultimate Karma that applies equally to everyone, even God, 9:16", "approx_sec": 5.0}]}' WHERE id = 'gandhari_curse';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "karna_wheel", "title": "कर्ण के रथ का पहिया", "category": "महाभारत रहस्य", "estimated_speech_sec": 105.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "कर्ण के रथ का पहिया ज़मीन में क्यों धंस गया?", "image_prompt": "A majestic glowing chariot wheel stuck deep into thick, dark mud on a bloody battlefield, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "कर्ण एक अजेय योद्धा था।", "image_prompt": "Karna standing tall on his glowing chariot, pulling his heavy bow with golden arrows flying towards the enemy, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "लेकिन उसे एक भयंकर श्राप मिला था।", "image_prompt": "A flashback showing an angry Brahmin pointing a cursing finger at Karna, dark clouds overhead, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "एक बार उसने अनजाने में गाय का बछड़ा कुचल दिया था।", "image_prompt": "A small innocent calf lying dead near the large wooden wheel of Karna''s chariot in a peaceful forest, 9:16", "approx_sec": 6.0}, {"slide_index": 5, "caption": "ब्राह्मण ने असहाय मरने का श्राप दिया।", "image_prompt": "The glowing curse leaving the Brahmin''s mouth and attaching itself to Karna''s chariot wheel, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "महाभारत के 17वें दिन श्राप सच हुआ।", "image_prompt": "Epic battle between Arjuna''s glowing white chariot and Karna''s golden chariot, massive energy waves, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "कर्ण के रथ का पहिया अचानक धंस गया।", "image_prompt": "The heavy golden wheel of Karna''s chariot abruptly sinking deep into soft, muddy soil, tilting the chariot, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "कर्ण पहिया निकालने लगा।", "image_prompt": "Karna stepping down from the chariot without his bow, trying desperately with both hands to lift the heavy wheel from the mud, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "उसने अ